'use strict';
const $=s=>document.querySelector(s), $$=s=>Array.from(document.querySelectorAll(s));
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('es-AR',{style:'currency',currency:'ARS',maximumFractionDigits:0}).format(Number(n)||0);
const n=x=>Number(x)||0;
const dateES=s=>{if(!s)return '—';const d=new Date(String(s).slice(0,10)+'T12:00:00Z');return !isNaN(d)?new Intl.DateTimeFormat('es-AR',{day:'2-digit',month:'short',year:'numeric',timeZone:'UTC'}).format(d):s};
const datetime=s=>s?`${dateES(s)} · ${String(s).slice(11,16)}`:'—';
const today=()=>new Date(Date.now()-3*3600000).toISOString().slice(0,10);
const printColorOptions=[['','Seleccioná el color'],['Blanco','Blanco'],['Negro','Negro'],['Gris','Gris'],['Rojo','Rojo'],['Azul','Azul'],['Verde','Verde'],['Amarillo','Amarillo'],['Naranja','Naranja'],['Rosa','Rosa'],['Violeta','Violeta'],['Transparente','Transparente'],['Otro color, aclarar por WhatsApp','Otro color, aclarar por WhatsApp'],['Varios colores, aclarar por WhatsApp','Varios colores, aclarar por WhatsApp'],['Sin preferencia de color','Sin preferencia de color']];
const requiredColorField=()=>selectField('Color de impresión *','color',printColorOptions,'').replace('name="color"','name="color" required');
const printServices=new Set(['impresion','modelado_impresion','repuestos','prototipos','catalogo','universitarios']);
const serviceNames={impresion:'Impresión 3D por encargo',modelado:'Solo diseño y modelado',modelado_impresion:'Modelado + impresión',repuestos:'Repuestos a medida',prototipos:'Prototipos',catalogo:'Productos de catálogo',universitarios:'Maquetas y proyectos universitarios'};
const statusNames={nueva:'Nueva solicitud',revision:'En revisión',faltan_datos:'Faltan datos',cotizada:'Presupuesto preparado',esperando_anticipo:'Esperando anticipo',confirmada:'Pedido confirmado',modelando:'En modelado',aprobacion:'Esperando aprobación',en_cola:'En cola de impresión',imprimiendo:'Imprimiendo',terminaciones:'Terminaciones',lista:'Listo para entregar',entregado:'Entregado',cancelado:'Cancelado',rechazado:'Rechazado',pausado:'Pausado'};
const statusColors={nueva:'blue',revision:'amber',faltan_datos:'amber',cotizada:'blue',esperando_anticipo:'amber',confirmada:'green',modelando:'blue',aprobacion:'amber',en_cola:'blue',imprimiendo:'blue',terminaciones:'blue',lista:'green',entregado:'green',cancelado:'red',rechazado:'red',pausado:'amber'};
const defaultPublic={brand:'GT-3D',tagline:'Tus ideas, hechas realidad.',city:'Rosario y alrededores',whatsapp:'5493412140690',instagram:'https://www.instagram.com/gt3d.impresiones/',email:'gt3drosario@gmail.com',pickup:'Retiro coordinado en Rosario',delivery_note:'Sin entrega a domicilio',public_pla_days:'5 a 10 días hábiles',public_design_days:'5 a 15 días hábiles',public_university_days:'5 a 15 días hábiles',public_catalog_days:'2 a 3 días hábiles'};
const state={public:{settings:defaultPublic,products:[],reviews:[]},admin:null,authenticated:false,tab:'inicio',sort:'todas',selOrder:null,activeMachine:1,load:false};
const app=$('#app'),modal=$('#modal-root');
function toast(msg,bad=false){const t=$('#toast');t.textContent=msg;t.classList.toggle('error',bad);t.classList.add('show');clearTimeout(toast._tid);toast._tid=setTimeout(()=>t.classList.remove('show'),4400)}
async function api(url,opts={}){const headers={'Content-Type':'application/json',...(opts.headers||{})};const res=await fetch(url,{...opts,headers,credentials:'same-origin'});const isJSON=(res.headers.get('content-type')||'').includes('json');const data=isJSON?await res.json():await res.text();if(!res.ok){const err=new Error(data?.error||`Error ${res.status}`);err.status=res.status;throw err;}return data}
const post=(url,b)=>api(url,{method:'POST',body:JSON.stringify(b)}), patch=(url,b)=>api(url,{method:'PATCH',body:JSON.stringify(b)}),del=url=>api(url,{method:'DELETE'});
async function freshPublic(){try{state.public=await api('/api/public')}catch(e){toast('No se pudo conectar con el servidor: '+e.message,true)}}
async function freshAdmin(){try{state.admin=await api('/api/admin/state');state.authenticated=true;}catch(e){if(e.status===401){state.authenticated=false;state.admin=null;}else toast('No se pudieron actualizar los datos del panel: '+e.message,true);}}
async function bootstrap(){await freshPublic();try{state.authenticated=(await api('/api/me')).authenticated;if(state.authenticated)await freshAdmin()}catch{};render();}
function render(){const hash=decodeURIComponent(location.hash.replace(/^#/,''));if(hash.startsWith('opinar/')){renderPublic();reviewByToken(hash.split('/')[1]);return;}if(hash.startsWith('admin')){const tab=hash.split('/')[1]||'inicio';state.tab=tab;renderAdmin();}else{renderPublic();if(hash)requestAnimationFrame(()=>document.getElementById(hash)?.scrollIntoView({behavior:'smooth'}));}}
function navPublic(){const s=state.public.settings;return `<header class="header"><div class="container topbar"><a href="#inicio" class="brand"><img class="brand-logo" src="/assets/logo-principal.png" alt="Logo GT-3D"><span>GT<span style="color:#7fa4b8">—</span>3D<small>IMPRESIÓN · ROSARIO</small></span></a><nav class="navlinks" id="main-nav"><a href="#servicios">Servicios</a><a href="#como-funciona">Cómo trabajamos</a><a href="#catalogo">Catálogo</a><a href="#plazos">Plazos y pagos</a><a href="#opiniones">Opiniones</a><a href="#contacto">Contacto</a></nav><div class="header-actions"><a class="btn btn-dark btn-sm" href="#admin/inicio">⚙ Panel privado</a><button class="hamburger" data-action="menu">☰</button></div></div></header>`;}
function productArt(p){return `<button type="button" class="product-art photo-art product-photo-trigger" data-action="view-product-photo" data-id="${Number(p.id)}" aria-label="Ver foto completa de ${esc(p.title)}"><img loading="lazy" src="/api/product-image/${Number(p.id)}?v=${encodeURIComponent(p.photo_rev||'original')}" alt="Fotografía de ${esc(p.title)}"><span class="product-photo-cue" aria-hidden="true">⤢ Ver foto completa</span></button>`;}
function printerSVG(){return `<svg class="product-illustration" viewBox="0 0 450 440" role="img" aria-label="Ilustración de una impresora 3D de escritorio" xmlns="http://www.w3.org/2000/svg"><defs><linearGradient id="metal" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#647784"/><stop offset="1" stop-color="#263846"/></linearGradient><linearGradient id="obj" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#d4f693"/><stop offset="1" stop-color="#7eb035"/></linearGradient></defs><ellipse cx="230" cy="390" rx="170" ry="24" fill="#08121c" opacity=".65"/><path d="M87 63h266v312H87z" fill="none" stroke="url(#metal)" stroke-width="19"/><path d="M76 79h288M91 350h257" stroke="#87939a" stroke-width="8"/><path d="M111 247h245l30 41H87z" fill="#405766"/><path d="M101 274h269v52H101z" fill="#101d27" stroke="#52636e" stroke-width="6"/><path d="M119 276h230" stroke="#a2b8bf" stroke-width="4"/><path d="M155 265l37-57h76l37 57z" fill="url(#obj)" stroke="#8fc13b" stroke-width="5"/><path d="M197 207l32-42 40 43z" fill="#b9e569"/><path d="M226 172v-62" stroke="#9facb2" stroke-width="7"/><rect x="180" y="101" width="97" height="48" rx="9" fill="#182b38" stroke="#84939c" stroke-width="6"/><rect x="209" y="141" width="37" height="17" rx="4" fill="#aecf6b"/><path d="M138 75v110M311 75v110" stroke="#8ca0ad" stroke-width="8"/><circle cx="138" cy="159" r="9" fill="#afc0c7"/><circle cx="311" cy="159" r="9" fill="#afc0c7"/><path d="M83 347h275v35H83z" fill="#101c27" stroke="#81949e" stroke-width="5"/><rect x="114" y="357" width="66" height="14" rx="3" fill="#b8dd72"/><path d="M96 64V47h62V28h113v19h67v17" fill="none" stroke="#344c59" stroke-width="12"/><circle cx="356" cy="363" r="6" fill="#b9df74"/><path d="M142 379l-18 19M316 379l18 19" stroke="#141f29" stroke-width="12" stroke-linecap="round"/></svg>`}
function serviceCard(icon,title,description,code){return `<article class="service-card"><span class="icon-box">${icon}</span><h3>${title}</h3><p>${description}</p><button class="linkbtn" data-action="open-request" data-service="${code}">Solicitar presupuesto →</button></article>`}
function renderPublic(){const s=state.public.settings,products=state.public.products,reviews=state.public.reviews;const avg=reviews.length?reviews.reduce((a,r)=>a+n(r.rating),0)/reviews.length:0;app.innerHTML=navPublic()+`<main id="inicio">${state.public.demo?'<div class="demo-warning" role="status"><strong>🧪 Sitio de prueba de GT-3D.</strong> No se están tomando encargos reales. Los datos y las fotos subidas pueden borrarse al reiniciarse el servidor. Usá información ficticia.</div>':''}<section class="hero"><div class="container hero-grid"><div><span class="eyebrow">Fabricación digital en Rosario</span><h1>Ideas que toman <em>forma.</em></h1><p>Diseñamos, modelamos e imprimimos en 3D soluciones a medida. Desde el repuesto que no conseguís hasta ese proyecto que querés hacer realidad.</p><div class="hero-actions"><button class="btn" data-action="open-request" data-service="impresion">Pedir presupuesto ↗</button><a class="btn btn-white" href="#servicios">Explorar servicios ↘</a></div><div class="hero-chips"><span>✦ Atención personalizada</span><span>◈ Diseño a medida</span><span>⌖ Rosario y alrededores</span></div></div><div class="hero-visual">${printerSVG()}<span class="floating-card float-one">✦ Impresión <b>FDM</b></span><span class="floating-card float-two">◈ Piezas <b>personalizadas</b></span></div></div></section>
<section class="strip"><div class="container strip-inner"><span class="strip-item">✓ Presupuesto personalizado</span><span class="strip-item">✓ Fabricación bajo pedido</span><span class="strip-item">✓ Seguimiento por WhatsApp</span><span class="strip-item">✓ Retiro coordinado</span></div></section>
<section id="servicios" class="section"><div class="container"><div class="section-header"><span class="eyebrow">Lo que hacemos</span><h2>Servicios para hacer realidad tu idea</h2><p>Elegí lo que necesitás: te hacemos las preguntas justas y revisamos tu solicitud para cotizarla.</p></div><div class="cards4">${serviceCard('▤','Impresión 3D','¿Ya tenés un archivo STL, 3MF o STEP? Lo revisamos y fabricamos con el material adecuado.','impresion')}${serviceCard('✎','Diseño y modelado','Convertimos una idea o croquis en un archivo 3D.','modelado')}${serviceCard('◇','Modelado + impresión','Diseñamos tu pieza desde cero y también la fabricamos.','modelado_impresion')}${serviceCard('⚙','Repuestos a medida','Recreamos piezas y adaptadores para resolver problemas cotidianos o técnicos.','repuestos')}${serviceCard('◫','Prototipado','Creamos prototipos funcionales para evaluar ideas y diseños.','prototipos')}${serviceCard('✧','Productos propios','Llaveros, macetas y objetos personalizados disponibles por encargo.','catalogo')}${serviceCard('⌂','Maquetas y proyectos universitarios','Maquetas para Arquitectura, modelos a escala, piezas técnicas y prototipos para trabajos de facultad.','universitarios')}</div></div></section>
<section id="universitarios" class="university-section"><div class="container university-feature"><div><span class="eyebrow">Para estudiantes y equipos de proyecto</span><h2>Maquetas y piezas para la facultad</h2><p>Imprimimos componentes para maquetas de Arquitectura y Urbanismo, piezas para Ingeniería, prototipos y trabajos prácticos. Podemos trabajar a partir de archivos 3D listos o presupuestar el modelado y la adaptación de planos.</p><div class="university-tags"><span>Maquetas a escala</span><span>Edificios y urbanismo</span><span>Piezas técnicas</span><span>Prototipos</span></div><div class="university-actions"><button class="btn btn-dark" data-action="open-request" data-service="universitarios">Cotizar mi proyecto →</button><small>Plazo orientativo: ${esc(s.public_university_days||'5 a 15 días hábiles')}, con o sin modelado. Compartí medidas, cantidad y fecha límite académica; confirmamos la entrega después de revisar el proyecto y la agenda.</small></div></div><div class="university-diagram" aria-hidden="true"><div class="diagram-grid"><div class="diagram-tower tower-a"></div><div class="diagram-tower tower-b"></div><div class="diagram-tower tower-c"></div><div class="diagram-tower tower-d"></div></div><span class="diagram-label">MAQUETA · 1:100</span></div></div></section>
<section id="como-funciona" class="section alt"><div class="container"><div class="section-header center"><span class="eyebrow">Simple y transparente</span><h2>¿Cómo trabajamos?</h2><p>Todo empieza con tu solicitud. No necesitás conocimientos de impresión 3D.</p></div><div class="process-grid"><div class="process-item"><div class="step-number">01</div><h3>Contanos qué necesitás</h3><p>Elegí un servicio, completá el formulario y adjuntá referencias o archivos.</p></div><div class="process-item"><div class="step-number">02</div><h3>Recibí tu presupuesto</h3><p>Revisamos viabilidad, materiales, precio y fecha estimada antes de confirmar.</p></div><div class="process-item"><div class="step-number">03</div><h3>Confirmá el trabajo</h3><p>Aprobás las condiciones y abonás el anticipo correspondiente.</p></div><div class="process-item"><div class="step-number">04</div><h3>Fabricamos y entregamos</h3><p>Diseñamos cuando corresponde, imprimimos y coordinamos el retiro.</p></div></div></div></section>
<section id="catalogo" class="section"><div class="container"><div class="section-header"><span class="eyebrow">Productos & creaciones</span><h2>Un catálogo hecho para vos</h2><p>Estos productos pueden encargarse según sus variantes y disponibilidad. Los trabajos personalizados se presupuestan aparte.</p></div><div class="catalog-tools"><input id="catalog-search" type="search" aria-label="Buscar productos" placeholder="Buscar producto… (maceta, llavero, porta celular)"><select id="catalog-category" aria-label="Filtrar categoría"><option value="">Todas las categorías</option>${[...new Set(products.map(p=>p.category))].sort((a,b)=>a.localeCompare(b)).map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('')}</select><span id="catalog-count" class="catalog-count">${products.length} productos</span></div><div class="product-grid" id="catalog-grid">${products.length?products.map(p=>`<article class="product-card" data-name="${esc((p.title+' '+p.description).toLowerCase())}" data-cat="${esc(p.category)}">${productArt(p)}<div class="product-body"><h3>${esc(p.title)}</h3><p>${esc(p.description)}</p><div class="product-foot"><b>${n(p.price)>0?money(p.price):'A cotizar'}</b><button class="btn btn-sm" data-action="open-request" data-service="catalogo" data-product="${esc(p.title)}">Consultar ↗</button></div></div></article>`).join(''):`<div class="empty">Próximamente publicaremos más productos.</div>`}</div><div class="info-banner mt-lg"><div><b>¿Tenés un diseño distinto en mente?</b><p>Podemos modelarlo y fabricarlo. Mandanos una descripción, medidas o referencias.</p></div><button class="btn btn-dark" data-action="open-request" data-service="modelado">Contanos tu idea →</button></div></div></section>
<section id="plazos" class="section alt"><div class="container timing-grid"><div class="section-header"><span class="eyebrow">Antes de encargar</span><h2>Plazos, pagos y entregas claras.</h2><p>Los tiempos dependen de cada diseño, la duración de impresión y la disponibilidad real del taller. Te damos una fecha de entrega antes de confirmar tu pedido.</p><div class="timing-notice"><b>¿Cuándo empieza el plazo?</b><br>Desde que se acepta el presupuesto, se acredita el anticipo y contamos con la información o diseño aprobado necesarios. La fecha solicitada no es un compromiso hasta que te la confirmemos.</div></div><div><div class="simple-list"><div class="list-item"><span>◷ Impresión con archivo listo</span><small>${esc(s.public_pla_days)}</small></div><div class="list-item"><span>✎ Diseño y modelado</span><small>${esc(s.public_design_days)}</small></div><div class="list-item"><span>◇ Modelado + impresión</span><small>${esc(s.public_design_days)}</small></div><div class="list-item"><span>⚙ Repuestos con modelado</span><small>${esc(s.public_design_days)}</small></div><div class="list-item"><span>◫ Prototipos con modelado</span><small>${esc(s.public_design_days)}</small></div><div class="list-item"><span>⌂ Maquetas y proyectos universitarios (con o sin modelado)</span><small>${esc(s.public_university_days||'5 a 15 días hábiles')}</small></div><div class="list-item"><span>▣ Productos de catálogo, sin modelado adicional</span><small>${esc(s.public_catalog_days||'2 a 3 días hábiles')}</small></div><div class="list-item"><span>↳ Retiro coordinado</span><small>Coordinado</small></div></div><p class="form-help mt">Para maquetas y proyectos universitarios, el plazo es el mismo con o sin modelado. En los demás servicios, cuando un repuesto, prototipo o producto de catálogo requiere diseñar o modelar una pieza nueva, se aplica el plazo de modelado; con un archivo listo se aplica el de impresión. Los plazos son orientativos desde la confirmación del pedido. Anticipo únicamente por transferencia; el saldo puede pagarse por transferencia o efectivo. Retiro coordinado en Rosario y alrededores. Atención en días hábiles de 8 a 19 h.</p></div></div></section>
<section id="opiniones" class="section"><div class="container"><div class="review-top"><div class="section-header"><span class="eyebrow">Experiencias reales</span><h2>Lo que dicen nuestros clientes</h2><p>Opiniones verificadas de pedidos entregados. Valoramos todas las experiencias para seguir mejorando.</p></div><div class="text-right"><div class="stars">${reviews.length?'★★★★★':'☆☆☆☆☆'}</div><strong style="font-size:22px">${reviews.length?avg.toFixed(1).replace('.',',')+' / 5':'Sin calificaciones todavía'}</strong><div class="muted" style="font-size:11px">${reviews.length} ${reviews.length===1?'reseña':'reseñas'} publicadas</div></div></div>${reviews.length?`<div class="reviews-grid">${reviews.map(r=>`<article class="review-card"><div class="stars">${'★'.repeat(n(r.rating))}${'☆'.repeat(5-n(r.rating))}</div><p>“${esc(r.comment)}”</p><strong>${esc(r.name)}</strong><small>✓ Cliente verificado · ${esc(serviceNames[r.service]||r.service)} · ${dateES(r.created_at)}</small>${r.reply?`<small><b>Respuesta GT-3D:</b> ${esc(r.reply)}</small>`:''}</article>`).join('')}</div>`:`<div class="empty"><div class="empty-icon">☆</div><h3>Pronto verás las primeras opiniones</h3><p>Publicaremos comentarios auténticos de clientes que hayan recibido sus pedidos.</p></div>`}<p class="form-help mt">Después de retirar o recibir su pedido, cada cliente puede calificar el servicio mediante un enlace único enviado por WhatsApp.</p></div></section>
<section id="contacto" class="contact-section"><div class="container contact-layout"><div><span class="eyebrow">Hablemos de tu proyecto</span><h2>Lo fabricamos juntos.</h2><p>Atendemos pedidos en Rosario y alrededores, con retiro coordinado. Contanos qué necesitás y te preparamos un presupuesto personalizado.</p><div class="hero-actions"><button class="btn" data-action="open-request" data-service="impresion">Solicitar presupuesto ↗</button></div></div><div class="contact-actions"><button data-action="contact-whatsapp"><span>✆ WhatsApp</span><span>↗</span></button>${s.instagram?`<a href="${safeLink(s.instagram)}" target="_blank" rel="noopener noreferrer"><span>◎ Instagram</span><span>↗</span></a>`:''}${s.email?`<a href="mailto:${esc(s.email)}"><span>✉ Correo electrónico</span><span>↗</span></a>`:''}<div style="font-size:12px;color:#a8bac4;padding:10px">⌖ ${esc(s.city)} · ${esc(s.pickup)}</div></div></div></section></main><footer class="footer"><div class="container footer-inner"><div class="brand"><img class="brand-logo" src="/assets/logo-principal.png" alt="Logo GT-3D"><span>GT—3D</span></div><div>Rosario, Santa Fe · Impresión & diseño 3D</div><div>© ${new Date().getFullYear()} GT-3D</div><a href="mailto:${esc(s.email)}?subject=Privacidad%20GT-3D">Privacidad y datos ↗</a><a href="#admin/inicio">Administración ↗</a></div></footer><button class="floating-whatsapp" aria-label="Consultar por WhatsApp" data-action="contact-whatsapp">✆</button>`;}
function safeLink(link){const s=String(link||'').trim();if(s.startsWith('https://'))return esc(s);if(s.startsWith('@'))return 'https://instagram.com/'+encodeURIComponent(s.slice(1));return '#contacto';}
function whatsappTo(number,text){
 let raw=String(number||'').replace(/\D/g,'').replace(/^00/,'');
 if(raw.startsWith('549'))raw=raw.slice(3);
 else if(raw.startsWith('54'))raw=raw.slice(2);
 raw=raw.replace(/^0+/,'');
 // Algunos clientes anotan el "15" después del código de área rosarino 341.
 if(raw.startsWith('34115')&&raw.length===12)raw='341'+raw.slice(5);
 if(raw.length!==10){toast('WhatsApp incompleto: ingresá código de área y número, por ejemplo 3415551234.',true);return;}
 window.open(`https://wa.me/549${raw}?text=${encodeURIComponent(text)}`,'_blank','noopener,noreferrer');
}
function whatsapp(text){whatsappTo(state.public.settings.whatsapp,text)}
function modalOpen(title,content,wide=false){modal.innerHTML=`<div class="modal-backdrop" data-close="backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-header"><h2>${esc(title)}</h2><button class="close" aria-label="Cerrar" data-action="close-modal">×</button></div><div class="modal-body">${content}</div></section></div>`;document.body.style.overflow='hidden';}
function modalClose(){modal.innerHTML='';document.body.style.overflow='';if(photoObjectURL){URL.revokeObjectURL(photoObjectURL);photoObjectURL=null;}}
function viewProductPhoto(id){
 const product=state.public.products.find(p=>Number(p.id)===Number(id));
 if(!product)return;
 const src=`/api/product-image/${Number(product.id)}?v=${encodeURIComponent(product.photo_rev||'original')}`;
 modalOpen(product.title,`<div class="product-photo-full"><img src="${src}" alt="Foto completa de ${esc(product.title)}"></div><p class="form-help product-photo-hint">Imagen completa del producto, sin recortes.</p>`,true);
}

function field(label,name,type='text',val='',attrs=''){return `<div class="field"><label for="f_${name}">${label}</label><input id="f_${name}" name="${name}" type="${type}" value="${esc(val)}" ${attrs}></div>`;}
function selectField(label,name,opts,val=''){return `<div class="field"><label for="f_${name}">${label}</label><select name="${name}" id="f_${name}">${opts.map(x=>{const v=typeof x==='string'?x:x[0],txt=typeof x==='string'?x:x[1];return `<option value="${esc(v)}" ${String(v)===String(val)?'selected':''}>${esc(txt)}</option>`}).join('')}</select></div>`;}
function textareaField(label,name,val='',extra=''){return `<div class="field"><label for="f_${name}">${label}</label><textarea name="${name}" id="f_${name}" ${extra}>${esc(val)}</textarea></div>`;}
function dataForm(form){return Object.fromEntries(new FormData(form).entries())}
function requestFields(service){
 const uni=service==='universitarios';
 const common=`${field('Nombre y apellido *','client_name','text','','required minlength="2" maxlength="100" autocomplete="name" placeholder="Ej. Juan Pérez"')}${field('WhatsApp con característica *','phone','tel','','required maxlength="35" autocomplete="tel" inputmode="tel" placeholder="Ej. 341 123 4567"')}<div class="span2 request-help">Usamos tu WhatsApp únicamente para responder el presupuesto. Incluí el código de área.</div>`;
 const quantity=field('Cantidad de piezas *','quantity','number',1,'min="1" max="10000" step="1" required');
 const product=service==='catalogo'?field('Producto seleccionado (opcional)','product','text','','placeholder="¿Qué producto del catálogo te interesa?"'):'';
 const primary=uni?`${selectField('Tipo de proyecto (opcional)','project_type',[['','No estoy seguro/a'],['Maqueta arquitectónica','Maqueta arquitectónica'],['Maqueta urbana','Maqueta urbana'],['Piezas para maqueta','Piezas para maqueta'],['Proyecto de Ingeniería','Proyecto de Ingeniería'],['Prototipo universitario','Prototipo universitario'],['Otro','Otro']])}${selectField('Archivos disponibles (opcional)','files_ready',[['','No sé / Necesito orientación'],['Tengo STL / 3MF listos para imprimir','Tengo STL / 3MF listos para imprimir'],['Tengo CAD / planos y necesitan revisión','Tengo CAD / planos y necesitan revisión'],['Necesito modelar o adaptar piezas','Necesito modelar o adaptar piezas'],['Todavía no tengo archivos','Todavía no tengo archivos']])}`:product;
 let extra='';
 if(uni)extra=`${field('Carrera o disciplina (opcional)','career','text','','maxlength="120" placeholder="Ej. Arquitectura"')}${field('Medidas aproximadas (opcional)','dimensions','text','','maxlength="120" placeholder="Ej. 30 × 40 × 15 cm"')}${selectField('Material preferido (opcional)','material',['No sé, necesito orientación','PLA','PLA+','PETG','TPU'])}${selectField('Nivel de terminación (opcional)','finish',['Necesito asesoramiento','Estándar, sin pintar','Alta definición / detalle fino'])}${field('Enlace a archivos grandes (opcional)','reference_link','url','','maxlength="500" placeholder="https://drive.google.com/..."')}`;
 else if(service==='impresion')extra=`${selectField('Material (opcional)','material',['No sé, necesito orientación','PLA','PLA+','PETG','TPU'])}${selectField('Uso de la pieza (opcional)','usage',['No sé / A consultar','Decorativo','Funcional','Repuesto','Prototipo','Otro'])}${selectField('Terminación (opcional)','finish',['A consultar','Estándar','Fina'])}`;
 else if(['modelado','modelado_impresion','prototipos'].includes(service))extra=`${selectField('Resultado deseado (opcional)','design_result',service==='modelado'?['A definir','Solo archivo digital','Modelo digital + impresión']:['A definir','Modelo digital + impresión','Solo archivo digital'])}${field('Medidas aproximadas (opcional)','dimensions','text','','placeholder="Ej. 10 × 5 × 3 cm"')}${selectField('Tipo de diseño (opcional)','design_type',['No sé / A consultar','Pieza mecánica','Objeto decorativo','Accesorio','Otro'])}`;
 else if(service==='repuestos')extra=`${field('Máquina u objeto al que pertenece (opcional)','reference','text','','placeholder="Ej. ventilador de pie"')}${field('Medidas aproximadas (opcional)','dimensions','text','','placeholder="Ej. 4 × 3 cm"')}${selectField('Condiciones de uso (opcional)','stress',['No sé / Necesito orientación','Esfuerzo mecánico','Temperatura','Flexibilidad','Otro'])}${selectField('¿Tenés la pieza original? (opcional)','original',['No sé / A consultar','Sí','No','Está rota'])}`;
 else extra=`${field('Personalización (opcional)','personalization','text','','placeholder="Ej. con nombre grabado"')}`;
 const eta=uni?'5 a 15 días hábiles, con o sin modelado':service==='catalogo'?'2 a 3 días hábiles para productos estándar':service==='modelado'||service==='modelado_impresion'?'5 a 15 días hábiles':'5 a 10 días hábiles para impresión, o 5 a 15 si requiere modelado';
 const descriptionHint=uni?'Contanos qué querés fabricar y para qué lo necesitás. Si sabés la escala o las medidas, podés escribirlas acá.':service==='catalogo'?'Decinos qué producto querés, cuántos y si necesitás alguna modificación.':'Contanos qué querés hacer y para qué lo vas a usar. No necesitás conocer términos técnicos.';
 return `<p class="request-lead">Pedí tu presupuesto sin compromiso. <b>No pagás ni confirmás el pedido ahora.</b> Te responderemos por WhatsApp con el precio y el plazo, después de revisar tu solicitud.</p>
 <form id="request-form" data-service="${esc(service)}">
 <div class="request-section-title">1. Tus datos <span>Solo 2 campos</span></div><p class="request-requirements">Los campos con * son obligatorios. Todo lo demás es opcional.</p>
 <div class="form-grid">${common}</div>
 <div class="request-section-title">2. ¿Qué necesitás?</div>
 <div class="form-grid">${primary}${quantity}${printServices.has(service)?`${requiredColorField()}<div class="span2 request-help">Si necesitás varios colores, elegí esa opción y aclaralos por WhatsApp después de enviar la solicitud.</div>`:''}<div class="span2">${textareaField('Descripción del trabajo *','description','','required minlength="8" maxlength="1200" placeholder="'+esc(descriptionHint)+'"')}</div></div>
 <details class="request-extras"><summary>+ Agregar más detalles <span>(opcional)</span></summary><p class="request-help">Si no sabés el material, las medidas o la terminación, dejalos sin completar. Nosotros te asesoramos.</p><div class="form-grid">${extra}</div></details>
 <div class="request-section-title">3. Fecha y archivos <span>Opcional</span></div><p class="request-help request-eta"><b>Plazo orientativo:</b> ${esc(eta)}. La fecha final se confirma al revisar el trabajo.</p>
 <div class="form-grid"><div class="span2">${selectField('¿Tenés una fecha límite? (opcional)','date_choice',[['undefined','Sin definir'],['date','Sí, necesito para una fecha']],'undefined')}</div><div class="span2 request-date-wrapper" id="request-date-wrapper" hidden>${field('Fecha que necesitás *','desired_date','date','','disabled')}<small>No es una fecha de entrega confirmada; te informaremos la disponibilidad antes de aceptar el pedido.</small></div>
 <div class="span2 field"><label for="request-files">Adjuntar archivos o fotos (opcional)</label><input id="request-files" name="files" type="file" multiple accept=".stl,.3mf,.step,.stp,.obj,.dxf,.dwg,.skp,.ifc,.png,.jpg,.jpeg,.webp,.pdf"><small>Podés enviarnos planos, fotos o archivos 3D. Hasta 4 archivos; 5 MB cada uno y 12 MB en total. <b>Si pesan demasiado, registrá la solicitud y mandalos después por WhatsApp indicando el código de pedido.</b></small><p id="request-file-status" class="request-file-status" role="status" aria-live="polite">No agregaste archivos; podés continuar igualmente.</p><button type="button" class="btn btn-ghost btn-xs request-clear-files" data-action="clear-request-files" hidden>Quitar archivos seleccionados</button></div></div>
 <p class="request-pickup">⌖ Trabajamos en Rosario y alrededores. El retiro es coordinado; no hacemos envíos a domicilio.</p>
 <label class="privacy-consent"><input type="checkbox" name="privacy_consent" required> <span><b>Obligatorio:</b> autorizo a GT-3D a usar mis datos y archivos solamente para responder y gestionar esta solicitud. Podré consultar o solicitar su eliminación por correo electrónico.</span></label>
 <div class="modal-actions"><button type="button" class="btn btn-ghost" data-action="close-modal">Cancelar</button><button type="submit" class="btn" id="request-send">Solicitar presupuesto sin pagar →</button></div>
 </form>`;
}
function syncRequestDate(form){
 const choice=form?.querySelector('[name="date_choice"]');const date=form?.querySelector('[name="desired_date"]');const wrapper=form?.querySelector('#request-date-wrapper');
 if(!choice||!date||!wrapper)return;
 const enabled=choice.value==='date';wrapper.hidden=!enabled;date.disabled=!enabled;date.required=enabled;
 if(!enabled)date.value='';else date.min=today();
}
function validateRequestFiles(form){
 const input=form?.querySelector('[name="files"]');const help=form?.querySelector('#request-file-status');if(!input)return '';
 const files=Array.from(input.files||[]),bytes=files.reduce((acc,f)=>acc+f.size,0);
 let issue='';if(files.length>4)issue='Elegiste más de 4 archivos. Quitá algunos o envialos después por WhatsApp.';
 else if(files.some(f=>f.size>5e6))issue='Uno de los archivos supera 5 MB. Podés enviarlo después por WhatsApp.';
 else if(bytes>12e6)issue='Los archivos superan 12 MB en total. Podés enviar los más grandes después por WhatsApp.';
 if(help){help.classList.toggle('error',Boolean(issue));help.textContent=issue||(!files.length?'No agregaste archivos; podés continuar igualmente.':`${files.length} archivo${files.length===1?' seleccionado':'s seleccionados'} · listo para enviar.`);}
 const clear=form?.querySelector('.request-clear-files');if(clear)clear.hidden=!files.length;
 return issue;
}
function validateRequestContact(form){
 const phone=form.querySelector('[name="phone"]');if(!phone)return true;
 const digits=phone.value.replace(/\D/g,'');
 phone.setCustomValidity(phone.value.trim()&&digits.length<8?'Ingresá tu WhatsApp con característica (por ejemplo, 341 123 4567).':'');
 return form.reportValidity();
}
function openRequest(service,product=''){if(!serviceNames[service])service='impresion';modalOpen('Solicitar · '+serviceNames[service],requestFields(service),true);if(product){const p=$('#request-form [name="product"]');if(p)p.value=product;const d=$('#request-form [name="description"]');if(d)d.value='Quiero consultar por '+product+' y conocer las opciones disponibles.';}}
function readFile(file){return new Promise((resolve,reject)=>{const rd=new FileReader();rd.onload=()=>resolve(String(rd.result).split(',')[1]);rd.onerror=reject;rd.readAsDataURL(file);});}
async function submitRequest(form){if(form.dataset.submitting==='true')return;syncRequestDate(form);if(!validateRequestContact(form))return;const fileIssue=validateRequestFiles(form);if(fileIssue)throw new Error(fileIssue);if(!form.reportValidity())return;form.dataset.submitting='true';const data=dataForm(form);if(printServices.has(form.dataset.service)&&!data.color)throw new Error('Seleccioná un color de impresión o la opción «Varios colores, aclarar por WhatsApp».');data.delivery='Retiro coordinado';if(data.date_choice!=='date')data.desired_date='';delete data.date_choice;const files=Array.from(form.querySelector('[name="files"]').files||[]);if(files.length>4)throw new Error('Podés adjuntar hasta 4 archivos. Quitá los demás y, después de registrar la solicitud, envialos por WhatsApp indicando el código del pedido.');for(const f of files)if(f.size>5e6)throw new Error('El archivo «'+f.name+'» supera los 5 MB. Quitalo de los adjuntos, registrá la solicitud y envialo por WhatsApp indicando el código del pedido.');if(files.reduce((sum,f)=>sum+f.size,0)>12e6)throw new Error('Los archivos superan los 12 MB en total. Quitá algunos, registrá la solicitud y enviá los restantes por WhatsApp indicando el código del pedido.');data.service=form.dataset.service;data.privacy_consent=Boolean(data.privacy_consent);data.details={usage:data.usage,finish:data.finish,design_result:data.design_result,dimensions:data.dimensions,design_type:data.design_type,reference:data.reference,stress:data.stress,original:data.original,product:data.product,personalization:data.personalization,university:data.university,career:data.career,course:data.course,project_type:data.project_type,files_ready:data.files_ready,scale:data.scale,reference_link:data.reference_link};delete data.files;data.files=await Promise.all(files.map(async f=>({name:f.name,mime:f.type,data:await readFile(f)})));const btn=$('#request-send');if(btn){btn.disabled=true;btn.textContent='Guardando solicitud...'}try{const result=await post('/api/requests',data);const msg=`Hola! Acabo de solicitar un presupuesto en GT-3D.\n\nSolicitud: ${result.code}\nServicio: ${serviceNames[data.service]}\nNombre: ${data.client_name}\nCantidad: ${data.quantity||1}\n${data.material?'Material: '+data.material+'\n':''}${data.color?'Color: '+data.color+'\n':''}${data.color==='Varios colores, aclarar por WhatsApp'?'Necesito estos colores: (detallar aquí)\n':''}${data.service==='universitarios'?'Proyecto: '+(data.project_type||'A definir')+'\nArchivos: '+(data.files_ready||'A definir')+'\n':''}Descripción: ${data.description}\n\nYa registré mi solicitud de presupuesto en la web. Archivos adjuntos allí: ${files.length}. Si tengo archivos grandes, los adjunto manualmente en este chat de WhatsApp. Quedo a la espera del presupuesto. Gracias!`;modalOpen('¡Solicitud recibida!',`<div style="text-align:center;padding:12px"><div class="empty-icon" style="font-size:50px">✓</div><h2 style="margin:8px 0">${esc(result.code)}</h2><p class="muted" style="line-height:1.8">Recibimos tu solicitud de presupuesto. <b>Aún no es un pedido confirmado y no tenés que pagar ahora.</b> Te contactaremos con precio y plazos. Abrí WhatsApp si querés continuar la conversación. <b>Si tenés archivos grandes, adjuntalos manualmente en el chat e indicá el código ${esc(result.code)}.</b> No se envían automáticamente por WhatsApp.</p><div class="modal-actions" style="justify-content:center"><button class="btn btn-dark" data-action="go-wa" data-message="${encodeURIComponent(msg)}">✆ Abrir WhatsApp</button><button class="btn btn-ghost" data-action="copy-msg" data-message="${encodeURIComponent(msg)}">Copiar mensaje</button></div>${!state.public.settings.whatsapp?'<p class="notice mt">WhatsApp comercial todavía no está configurado. Tu solicitud ya quedó guardada; podés copiar el mensaje.</p>':''}</div>`);toast('Solicitud '+result.code+' registrada correctamente');}catch(e){if(btn){btn.disabled=false;btn.textContent='Registrar solicitud →'}throw e;}}
async function reviewByToken(token){try{const x=await api('/api/review?token='+encodeURIComponent(token));if(x.submitted){modalOpen('Opinión ya registrada',`<p>Ya recibimos una opinión para el pedido <b>${esc(x.code)}</b>. ¡Gracias!</p>`);return;}modalOpen('Calificá tu experiencia',`<p class="muted mb">Pedido verificado: <b>${esc(x.code)}</b>. Tu opinión se revisará antes de publicarse. Las reseñas positivas y negativas son bienvenidas.</p><form id="review-form" data-token="${esc(token)}"><div class="field mb"><label>Calificación (1 a 5 estrellas)</label><div class="stars-select" id="review-stars">${[1,2,3,4,5].map(i=>`<button type="button" data-action="rate" data-value="${i}" aria-label="${i} estrellas">★</button>`).join('')}</div><input type="hidden" name="rating" value="0"></div>${field('Tu nombre o alias','name','text','')}${textareaField('Contanos qué te pareció el producto y la atención *','comment','', 'required minlength="8"')}<label class="switch mt"><input type="checkbox" name="anonymous"> Publicar como cliente verificado, sin mi nombre</label><div class="modal-actions"><button class="btn" type="submit">Enviar mi opinión</button></div></form>`);}catch(e){modalOpen('Enlace no disponible',`<p>${esc(e.message)}</p><p class="muted mt">Solicitá un nuevo enlace a GT-3D si ya recibiste tu pedido.</p>`);}}
function adminNav(){return [['inicio','◫','Inicio'],['pedidos','▤','Pedidos'],['cotizador','⌗','Cotizador'],['produccion','◷','Producción'],['inventario','▥','Inventario'],['finanzas','↗','Finanzas'],['catalogo','▦','Catálogo'],['resenas','☆','Reseñas'],['configuracion','⚙','Configuración']];}
function loginView(){app.innerHTML=`<div class="admin-login"><div class="login-card"><a class="brand" href="#inicio"><img class="brand-logo" src="/assets/logo-principal.png" alt="Logo GT-3D"><span>GT—3D<small>IMPRESIÓN · ROSARIO</small></span></a><span class="eyebrow">Acceso privado</span><h1>Panel de administración</h1><p>Gestioná pedidos, presupuestos, producción, inventario y finanzas desde un solo lugar.</p><form id="login-form"><div class="field"><label>Contraseña administrativa</label><input name="password" type="password" minlength="8" required autocomplete="current-password"></div><button class="btn btn-block mt" type="submit">Ingresar al panel →</button></form><p class="form-help mt">En Render, ingresá la contraseña que configuraste en la variable ADMIN_PASSWORD. No compartas esta clave con tus amigos.</p><a href="#inicio" class="link" style="display:inline-block;margin-top:18px">← Volver a la web pública</a></div></div>`;}
function renderAdmin(){if(!state.authenticated||!state.admin){loginView();return;}const items=adminNav();app.innerHTML=`<div class="admin-shell"><aside class="sidebar" id="sidebar"><a class="brand" href="#inicio"><img class="brand-logo" src="/assets/logo-principal.png" alt="Logo GT-3D"><span>GT—3D<small>ADMINISTRACIÓN</small></span></a><span class="label-nav">GESTIÓN DEL TALLER</span>${items.map(a=>`<a class="side-link ${state.tab===a[0]?'active':''}" href="#admin/${a[0]}"><span class="symbol">${a[1]}</span>${a[2]}</a>`).join('')}<div style="margin-top:auto;padding:20px 11px 5px"><div class="notice" style="font-size:10px">◈ Hellbot Magna 1 V2<br>Agenda variable · turnos nocturnos por fecha</div><button class="side-link" data-action="logout">↪ Cerrar sesión</button></div></aside><div class="admin-main"><div class="admin-top"><button class="admin-menu" data-action="toggle-sidebar">☰</button><span style="font-size:12px;color:var(--muted)">GT-3D <strong style="color:var(--ink)">/ ${items.find(x=>x[0]===state.tab)?.[2]||'Inicio'}</strong></span><div class="flex"><span class="badge green">● Panel privado · V2.9.6</span>${state.public.demo?'<span class="badge amber">🧪 DEMO / datos temporales</span>':''}<a class="btn btn-ghost btn-sm" href="#inicio">↗ Ver sitio web</a></div></div><main class="admin-page">${adminPage()}</main></div></div>`;}
const titleAdmin=(h,desc,action='')=>`<div class="admin-title-row"><div><span class="eyebrow">GT-3D / GESTIÓN</span><h1>${h}</h1><p>${desc}</p></div><div class="admin-actions">${action}</div></div>`;
const empty=(icon,t,d)=>`<div class="empty"><div class="empty-icon">${icon}</div><h3>${t}</h3><p>${d}</p></div>`;
const metric=(label,value,icon,sub='')=>`<div class="metric"><div class="meta"><span>${label}</span><span>${icon}</span></div><strong>${value}</strong><div class="sub">${sub}</div></div>`;
const badgeStatus=s=>`<span class="badge ${statusColors[s]||''}">${esc(statusNames[s]||s)}</span>`;
function adminPage(){const tab=state.tab;return ({inicio:dashboard,pedidos:ordersPage,cotizador:quotePage,produccion:productionPage,inventario:inventoryPage,finanzas:financesPage,catalogo:catalogPage,resenas:reviewsPage,configuracion:settingsPage}[tab]||dashboard)()}
function orderPaid(r){return (state.admin?.payments||[]).filter(p=>p.request_id===r.id).reduce((total,p)=>total+n(p.amount),0)}
function orderTransferPaid(r){return (state.admin?.payments||[]).filter(p=>p.request_id===r.id&&p.method==='Transferencia').reduce((total,p)=>total+n(p.amount),0)}
function nextOrderStep(r){
 const status=r.status,paid=orderPaid(r),transfer=orderTransferPaid(r);
 if(['cancelado','rechazado','entregado'].includes(status))return {label:'Finalizado',action:null,kind:'closed'};
 if(status==='faltan_datos')return {label:'Pedir datos al cliente',action:'order-request-info',kind:'quote'};
 if(['nueva','revision'].includes(status))return {label:'Revisar y cotizar',action:'order-quote',kind:'quote'};
 if(status==='cotizada')return {label:'Avisar presupuesto',action:'order-send-quote',kind:'send'};
 if(status==='esperando_anticipo'){
   if(transfer+0.01>=n(r.deposit)&&n(r.quote)>0)return {label:'Confirmar trabajo',action:'order-advance',to:'confirmada',kind:'confirm'};
   return {label:'Registrar anticipo',action:'order-add-payment',kind:'payment'};
 }
 if(status==='confirmada')return n(r.model_hours)>0?{label:'Iniciar modelado',action:'order-advance',to:'modelando',kind:'production'}:n(r.print_hours)>0?{label:'Programar impresión',action:'schedule-order',kind:'production'}:{label:'Preparar trabajo',action:'order-advance',to:'terminaciones',kind:'production'};
 if(status==='aprobacion')return n(r.print_hours)>0?{label:'Programar impresión tras aprobar diseño',action:'schedule-order',kind:'production'}:{label:'Diseño aprobado · finalizar',action:'order-advance',to:'terminaciones',kind:'production'};
 if(status==='modelando')return {label:'Pedir aprobación',action:'order-advance',to:'aprobacion',kind:'production'};
 if(status==='en_cola')return {label:'Iniciar impresión',action:'order-advance',to:'imprimiendo',kind:'production'};
 if(status==='imprimiendo')return {label:'Pasar a terminaciones',action:'order-advance',to:'terminaciones',kind:'production'};
 if(status==='terminaciones')return {label:'Marcar listo',action:'order-advance',to:'lista',kind:'ready'};
 if(status==='lista')return paid+0.01<n(r.quote)?{label:'Cobrar saldo',action:'order-add-payment',kind:'payment'}:{label:'Registrar entrega',action:'order-advance',to:'entregado',kind:'delivery'};
 return {label:'Revisar pedido',action:'order-detail',kind:'review'};
}
function stepButton(r,compact=false){const step=nextOrderStep(r);if(!step.action)return '';return `<button class="btn ${compact?'btn-xs':'btn-sm'} ${compact?'btn-ghost':''}" data-action="${step.action}" data-id="${r.id}" ${step.to?`data-status="${step.to}"`:''}>${esc(step.label)} →</button>`;}
function quickPayment(id){const r=state.admin?.requests.find(x=>x.id===id);if(!r)return;const remaining=Math.max(0,n(r.quote)-orderPaid(r));if(!remaining)return toast('El pedido ya está totalmente abonado.');const amount=Math.min(remaining,Math.max(0,n(r.deposit)-orderTransferPaid(r)))||remaining;openInputModal('Registrar pago · '+r.code,'payment-add',`<div class="form-grid"><input type="hidden" name="request_id" value="${r.id}">${field('Importe acreditado ($)','amount','number',amount,'required min="0.01" step="0.01"')}${selectField('Tipo','kind',[['anticipo','Anticipo'],['saldo','Saldo'],['pago completo','Pago completo']],orderTransferPaid(r)+0.01<n(r.deposit)?'anticipo':'saldo')}${selectField('Medio','method',['Transferencia','Efectivo'],orderTransferPaid(r)+0.01<n(r.deposit)?'Transferencia':'Efectivo')}${field('Fecha','date','date',today(),'required')}<div class="span2">${field('Nota','description','text','Pago verificado')}</div></div>`,`Saldo del pedido: ${money(remaining)}. Verificá que el dinero esté acreditado antes de registrarlo. Los anticipos son solo por transferencia.`);}
function dashboard(){const a=state.admin,r=a.requests,paid=a.payments.reduce((sum,x)=>sum+n(x.amount),0),expenses=a.expenses.reduce((sum,x)=>sum+n(x.amount),0),unpaid=r.filter(x=>!['cancelado','rechazado'].includes(x.status)).reduce((sum,x)=>sum+Math.max(0,n(x.quote)-a.payments.filter(p=>p.request_id===x.id).reduce((s,p)=>s+n(p.amount),0)),0),stock=a.inventory.filter(x=>n(x.stock)<=n(x.min_stock)),due=r.filter(x=>x.due_date&&!['entregado','cancelado','rechazado'].includes(x.status)).sort((x,y)=>x.due_date.localeCompare(y.due_date));return titleAdmin('Buen día, ¿qué hacemos hoy?','Resumen operativo del taller y prioridades para avanzar con cada trabajo.',`<button class="btn" data-action="open-request" data-service="impresion">+ Nuevo pedido</button>`)+`<div class="metric-grid">${metric('Solicitudes sin cotizar',r.filter(x=>['nueva','revision','faltan_datos'].includes(x.status)).length,'▤','Requieren revisión')}${metric('Pedidos activos',r.filter(x=>['confirmada','modelando','aprobacion','en_cola','imprimiendo','terminaciones','lista'].includes(x.status)).length,'◷','Confirmados y sin entregar')}${metric('Saldo pendiente',money(unpaid),'◉','De pedidos con presupuesto')}${metric('Caja acumulada',money(paid-expenses),'↗','Cobros registrados menos gastos')}</div><div class="admin-card mb"><div class="flex justify-between"><div><h3>Bandeja de próximas acciones</h3><p class="muted" style="margin:7px 0 0">Empezá por los pedidos que requieren una respuesta, un anticipo o una entrega.</p></div><a href="#admin/pedidos" class="btn btn-ghost btn-sm">Todos los pedidos →</a></div>${r.filter(x=>!['entregado','cancelado','rechazado'].includes(x.status)).sort((x,y)=>{const priority=z=>({nueva:0,revision:1,faltan_datos:2,cotizada:3,esperando_anticipo:4,lista:5})[z]??6;return priority(x.status)-priority(y.status)||x.id-y.id}).slice(0,8).map(x=>`<div class="stat-line" style="gap:12px;flex-wrap:wrap"><div><b>${esc(x.code)} · ${esc(x.client_name)}</b><br><small>${esc(serviceNames[x.service])} · ${esc(statusNames[x.status])}</small></div><div class="flex">${stepButton(x,true)}<button class="btn btn-ghost btn-xs" data-action="order-detail" data-id="${x.id}">Ficha</button></div></div>`).join('')||'<p class="muted mt">No hay tareas pendientes.</p>'}</div><div class="split"><div class="admin-card"><h3>Últimas solicitudes</h3>${r.length?`<div class="table-scroll"><table class="data-table"><thead><tr><th>Pedido</th><th>Cliente</th><th>Servicio</th><th>Estado</th><th></th></tr></thead><tbody>${r.slice(0,7).map(x=>`<tr><td><strong>${esc(x.code)}</strong><br><small>${dateES(x.created_at)}</small></td><td>${esc(x.client_name)}</td><td>${esc(serviceNames[x.service])}</td><td>${badgeStatus(x.status)}</td><td><button class="btn btn-ghost btn-xs" data-action="order-detail" data-id="${x.id}">Abrir</button></td></tr>`).join('')}</tbody></table></div>`:empty('▤','Sin solicitudes','Cuando alguien complete el formulario público, aparecerá acá.')}</div><div class="admin-card"><h3>Alertas y próximas entregas</h3>${a.scheduleWarnings.length?`<div class="notice mb">⚠ ${a.scheduleWarnings.length} trabajo(s) programados fuera de la disponibilidad actual. Revisá Producción.</div>`:''}${stock.length?`<div class="notice mb">▣ Stock bajo: ${stock.slice(0,3).map(x=>esc(x.name)).join(', ')}</div>`:''}${due.length?due.slice(0,5).map(x=>`<div class="stat-line"><span>${esc(x.code)} · ${esc(x.client_name)}</span><b>${dateES(x.due_date)}</b></div>`).join(''):empty('◷','Sin entregas programadas','Definí fechas comprometidas al confirmar trabajos.')}</div></div><div class="split-equal mt"><div class="admin-card"><h3>Accesos rápidos</h3><div class="flex"><a class="btn btn-ghost" href="#admin/cotizador">⌗ Hacer cotización</a><a class="btn btn-ghost" href="#admin/produccion">◷ Ver agenda</a><a class="btn btn-ghost" href="#admin/inventario">▥ Cargar material</a></div></div><div class="admin-card"><h3>El flujo de GT-3D</h3><p class="muted" style="line-height:1.8">Solicitud → Presupuesto → Anticipo confirmado → Diseño (si corresponde) → Producción → Pago final → Entrega → Opinión del cliente.</p></div></div>`;}
