function orderDetail(id){const r=state.admin.requests.find(x=>x.id===id);if(!r)return;state.selOrder=id;const p=state.admin.payments.filter(x=>x.request_id===id),paid=p.reduce((s,x)=>s+n(x.amount),0),base=location.origin;const reviewURL=base+'/#opinar/'+r.review_token;const wtext=`Hola ${r.client_name}! Te escribimos de GT-3D por el pedido ${r.code}. ${n(r.quote)>0?'El presupuesto es de '+money(r.quote)+'. ':''}¿Coordinamos los próximos pasos?`;modalOpen(`Pedido ${r.code}`,`<div class="details-grid mb">${[['Cliente',r.client_name],['WhatsApp',r.phone],['Servicio',serviceNames[r.service]],['Factor usado',r.pricing_multiplier?'×'+r.pricing_multiplier+(r.pricing_bulk?' (por cantidad)':''):'—'],['Precio definido',r.pricing_manual?'Manual':'Calculado'],['Ingreso',dateES(r.created_at)],['Solicitada',r.desired_date?dateES(r.desired_date):'Sin definir'],['Comprometida',dateES(r.due_date)],['Cobrado',money(paid)],['Saldo',money(Math.max(0,n(r.quote)-paid))]].map(x=>`<div class="detail-item"><span>${x[0]}</span><b>${esc(x[1])}</b></div>`).join('')}</div><p style="line-height:1.7;margin:10px 0">${esc(r.description)}</p><div class="details-grid mb">${[['Cantidad',r.quantity],['Material',r.material],['Color',r.color],['Localidad',r.city],['Correo',r.email],['Modalidad',r.delivery],...Object.entries(r.details||{}).filter(([key,val])=>val&&String(val)!=='undefined').map(([key,val])=>[({product:'Producto',personalization:'Personalización',usage:'Uso',finish:'Terminación',design_result:'Resultado solicitado',dimensions:'Medidas',design_type:'Tipo de diseño',reference:'Referencia',stress:'Condiciones de uso',original:'Pieza original',university:'Facultad',career:'Carrera',course:'Materia / taller',project_type:'Tipo de proyecto',files_ready:'Archivos disponibles',scale:'Escala',reference_link:'Enlace a archivos grandes'})[key]||key,val])].filter(([,value])=>value!==null&&value!==undefined&&String(value).trim()!==''&&String(value)!=='0').map(([label,value])=>`<div class="detail-item"><span>${esc(label)}</span><b>${esc(value)}</b></div>`).join('')}</div><div class="flex mb">${r.files.length?r.files.map(f=>`<button class="btn btn-ghost btn-xs" data-action="download-file" data-id="${f.id}">↓ ${esc(f.name)}</button>`).join(''):'<small>Sin archivos adjuntos</small>'}</div><form id="order-edit" data-id="${id}"><div class="form-grid">${selectField('Estado','status',Object.entries(statusNames),r.status)}${field('Fecha comprometida de entrega','due_date','date',r.due_date||'')}${field('Precio de venta ($)','quote','number',r.quote,'min="0" step="0.01"')}${field('Costo estimado ($)','cost','number',r.cost,'min="0" step="0.01"')}${field('Anticipo solicitado ($)','deposit','number',r.deposit,'min="0" step="0.01"')}${field('Horas de impresión','print_hours','number',r.print_hours,'min="0" step="0.01"')}${field('Horas de modelado','model_hours','number',r.model_hours,'min="0" step="0.01"')}${field('Filamento previsto (gramos)','grams','number',r.grams,'min="0" step="0.01"')}${field('Filamento realmente consumido (g)','actual_grams','number',r.actual_grams||r.grams,'min="0" step="0.01"')}${selectField('Impresora','machine_id',state.admin.machines.map(m=>[m.id,m.name]),r.machine_id)}<div class="span2"><label class="switch"><input type="checkbox" name="client_approved" ${r.client_approved?'checked':''}> El cliente aprobó el presupuesto (registrado por Admin)</label><small>Si cambiás el precio antes de confirmar, se vuelve a solicitar la aprobación.</small></div><div class="span2">${textareaField('Notas internas (solo Admin)','internal_notes',r.internal_notes||'')}</div></div><div class="modal-actions"><button type="submit" class="btn">Guardar cambios</button></div></form><hr class="sep"><div class="notice blue mb"><b>Próximo paso recomendado</b><div class="flex mt">${stepButton(r)} <button class="btn btn-ghost btn-sm" data-action="order-add-payment" data-id="${r.id}">+ Registrar pago</button></div>${n(r.deposit)>0?`<small>Anticipo por transferencia: ${money(orderTransferPaid(r))} / ${money(r.deposit)} · Saldo restante: ${money(Math.max(0,n(r.quote)-paid))}</small>`:''}</div><div class="flex"><button class="btn btn-ghost btn-sm" data-action="order-wa" data-id="${id}">✆ WhatsApp</button><button class="btn btn-ghost btn-sm" data-action="order-quote" data-id="${id}">⌗ Cotizar</button><button class="btn btn-ghost btn-sm" data-action="print-quote" data-id="${id}">▤ Imprimir presupuesto</button>${r.print_hours>0?`<button class="btn btn-ghost btn-sm" data-action="schedule-order" data-id="${id}">◷ Programar</button>`:''}</div>${r.planned_start?`<p class="notice blue mt">Impresión programada: <b>${datetime(r.planned_start)} → ${datetime(r.planned_end)}</b></p>`:''}<hr class="sep"><h3>Historial del pedido</h3><div class="timeline mt">${(state.admin.events||[]).filter(evt=>evt.request_id===r.id).slice(0,12).map(evt=>`<div class="timeline-item"><strong>${esc(evt.summary)}</strong><small>${esc(new Date(evt.created_at).toLocaleString('es-AR',{dateStyle:'short',timeStyle:'short',timeZone:'America/Argentina/Buenos_Aires'}))}</small></div>`).join('')||'<p class="muted">Sin movimientos todavía.</p>'}</div>${r.status==='entregado'?`<hr class="sep"><p class="muted mb">Enlace único para solicitar una opinión:</p><div class="flex"><input style="flex:1;min-width:180px;padding:9px;border:1px solid #ddd;border-radius:8px" readonly value="${esc(reviewURL)}"><button class="btn btn-ghost btn-sm" data-action="copy-review" data-id="${id}">Copiar enlace</button><button class="btn btn-ghost btn-sm" data-action="request-review" data-id="${id}">✆ Pedir reseña</button></div>`:''}`,true);}
function quotePage(){const a=state.admin,req=a.requests;const selected=state.selOrder&&req.some(r=>r.id===state.selOrder)?state.selOrder:(req[0]?.id||'');const selectedRequest=req.find(x=>x.id===selected);const machine=a.machines.find(x=>x.id===n(selectedRequest?.machine_id))||a.machines[0];const initialService=selectedRequest?.service||'impresion';const pureModel=initialService==='modelado';const material=a.inventory.filter(x=>x.category==='filamento');return titleAdmin('Cotizador inteligente','Calculá costos de impresión y modelado; guardá el presupuesto en la ficha del pedido.',`<button class="btn btn-ghost" data-action="new-manual">+ Nueva solicitud</button>`)+`<div class="split"><div class="admin-card"><form id="quote-form"><div class="form-grid">${selectField('Pedido a cotizar *','request_id',req.map(x=>[x.id,`${x.code} · ${x.client_name}`]),selected)}${selectField('Tipo de trabajo / multiplicador','pricing_service',Object.entries(serviceNames),req.find(x=>x.id===selected)?.service||'impresion')}${field('Cantidad total de unidades','quantity','number',req.find(x=>x.id===selected)?.quantity||1,'min="1" step="1"')}${selectField('Descuento por volumen (unidades repetibles)','bulk_mode',[['no','No aplicar'],['yes','Aplicar descuento escalonado según cantidad']],'no')}${selectField('Impresora','machine_id',a.machines.map(x=>[x.id,x.name]),machine?.id||1)}${selectField('Filamento en inventario','filament_id',[['','Seleccionar filamento'],...material.map(x=>[x.id,`${x.name} · ${money(x.cost_unit)}/g`])],selectedRequest?.filament_id||'')}${selectField('Accesorio o consumible','accessory_id',[['','Sin accesorio'],...a.inventory.filter(x=>x.category==='accesorio'||x.category==='consumible').map(x=>[x.id,`${x.name} · ${money(x.cost_unit)}/u`])])}${field('Unidades de accesorio','accessory_qty','number','0','min="0" step="1"')}${field('Gramos TOTALES del pedido (incluye soportes)','grams','number',n(selectedRequest?.grams)||0,'min="0" step="0.1"')}${field('Horas TOTALES de impresión del pedido','print_hours','number',n(selectedRequest?.print_hours)||0,'min="0" step="0.1"')}${field('Horas de modelado','model_hours','number',n(selectedRequest?.model_hours)||0,'min="0" step="0.1"')}${field('Preparación y retiro por pedido (min)','labor_minutes','number',a.settings.labor_default_minutes,'min="0" step="1"')}${field('Terminación por unidad (min)','unit_labor_minutes','number','0','min="0" step="1"')}${field('Otros costos (accesorios, embalaje, etc.)','extras','number','0','min="0" step="0.01"')}${field('Terminaciones especiales adicionales ($)','finish','number','0','min="0" step="0.01"')}${field('Precio manual opcional ($, 0 = calculado)','manual_price','number','0','min="0" step="100"')}</div><div class="notice blue mt">Para trabajos universitarios elegí «Maquetas y proyectos universitarios». Incluí las horas de modelado únicamente si hay que diseñar o adaptar archivos; la fabricación se calcula según gramos, horas de máquina, materiales y terminaciones. La fecha de examen no representa una entrega garantizada.</div><div class="notice blue mt">Para lotes, cargá gramos y horas TOTALES, no por unidad. Descuentos por cantidad para unidades repetibles: desde ${a.settings.bulk_min_quantity} (${a.settings.bulk_discount_first}%), ${a.settings.bulk_mid_quantity} (${a.settings.bulk_discount_mid}%) y ${a.settings.bulk_high_quantity} (${a.settings.bulk_discount_high}%). Se aplican sobre el factor de fabricación del servicio y no sobre el modelado. Los minutos de terminación por unidad se suman a los 15 minutos de preparación compartida. Modelado personalizado: $12.000/h y mínimo inicial de $8.000. Mano de obra de fabricación: $5.000/h y 15 minutos iniciales por pedido, editables en Configuración. La mano de obra solo se aplica si hay fabricación; modelado puro se cotiza aparte. Los costos de máquina se cambian en Producción.</div><div class="modal-actions"><button type="button" class="btn btn-ghost" data-action="recalc-quote">↻ Recalcular</button><button type="submit" class="btn">Guardar cotización →</button></div></form></div><div class="admin-card"><h3>Resultado de la cotización</h3><div id="quote-result">${empty('⌗','Completá los datos','El precio recomendado y su desglose se calcularán aquí.')}</div></div></div>`;}
function quoteCalc(){
  const form=$('#quote-form');if(!form||!state.admin)return null;
  const v=dataForm(form),a=state.admin,settings=a.settings;
  const request=a.requests.find(x=>x.id===n(v.request_id));
  const machineObj=a.machines.find(x=>x.id===n(v.machine_id))||a.machines[0];
  const filament=a.inventory.find(x=>x.id===n(v.filament_id));
  const accessory=a.inventory.find(x=>x.id===n(v.accessory_id));
  const quantity=Math.max(1,Math.floor(n(v.quantity)||n(request?.quantity)||1));
  const grams=n(v.grams),print=n(v.print_hours),model=n(v.model_hours);
  const accessoryCost=n(v.accessory_qty)*n(accessory?.cost_unit);
  const material=grams*n(filament?.cost_unit)*(1+n(settings.material_waste_pct)/100);
  const machine=print*n(machineObj?.cost_hour),extra=n(v.extras)+n(v.finish);
  const hasProduction=grams>0||print>0||accessoryCost>0||extra>0;
  const laborMinutes=hasProduction?n(v.labor_minutes)+n(v.unit_labor_minutes)*quantity:0;
  const laborCost=laborMinutes*n(settings.labor_rate)/60;
  const productionCost=material+machine+extra+accessoryCost+laborCost;
  const modelMultiplier=1; // La tarifa pactada de diseño YA es un precio, no un costo a remarcar.
  const modelSell=model>0?Math.max(model*n(settings.model_rate),n(settings.min_model)):0;
  const designCost=model*n(settings.model_cost_rate||0);
  const picked=Object.hasOwn(serviceNames,v.pricing_service)?v.pricing_service:(request?.service||'impresion');
  const pricingService=(hasProduction&&model>0&&['impresion','modelado','modelado_impresion'].includes(picked))?'modelado_impresion':picked;
  const bulkRequested=v.bulk_mode==='yes';
  const bulkMinimum=Math.max(2,Math.floor(n(settings.bulk_min_quantity)||10));
  const isBulk=hasProduction&&bulkRequested&&quantity>=bulkMinimum;
  const serviceKey='mult_'+pricingService;
  const serviceFactor=Math.max(1,n(settings[serviceKey])||2);
  const bulkDiscount=isBulk ? (quantity>=Math.max(bulkMinimum,n(settings.bulk_high_quantity)||50)?n(settings.bulk_discount_high):quantity>=Math.max(bulkMinimum,n(settings.bulk_mid_quantity)||25)?n(settings.bulk_discount_mid):n(settings.bulk_discount_first)) : 0;
  const multiplier=serviceFactor*(1-Math.min(40,Math.max(0,bulkDiscount))/100);
  const productionSell=hasProduction?Math.max(productionCost*multiplier,n(settings.min_print)):0;
  const recommended=Math.ceil((productionSell+modelSell+n(v.shipping))/100)*100;
  const isManual=n(v.manual_price)>0;
  const total=isManual?Math.ceil(n(v.manual_price)/100)*100:recommended;
  const estCost=productionCost+designCost+n(v.shipping);
  const profit=total-estCost;
  return {...v,quantity,pricingService,modelMultiplier,multiplier,isBulk,bulkDiscount,bulkRequested,bulkMinimum,serviceFactor,
    recommended,isManual,material,machine,accessoryCost,laborCost,laborMinutes,productionCost,productionSell,
    designCost,modelSell,total,estCost,profit,deposit:Math.ceil(total*n(settings.deposit_pct)/100),grams,print,model};
}
function renderQuoteResult(){const q=quoteCalc(),container=$('#quote-result');if(!q||!container)return;
const markup=q.isBulk?`${serviceNames[q.pricingService]||q.pricingService} · lote con ${q.bulkDiscount}% de descuento sobre el factor de fabricación`:(serviceNames[q.pricingService]||q.pricingService);
const rows=[['Filamento y desperdicio',q.material],['Tiempo de máquina',q.machine],['Mano de obra de fabricación ('+q.laborMinutes+' min)',q.laborCost],['Otros costos y terminación',n(q.extras)+n(q.finish)],['Accesorios',q.accessoryCost],['Costo total de fabricación',q.productionCost],['Fabricación con multiplicador ×'+q.multiplier,q.productionSell],['Modelado a '+money(n(state.admin.settings.model_rate))+'/h (sin recargo de fabricación)',q.modelSell],['Precio recomendado',q.recommended],['Costo total estimado',q.estCost],['Diferencia precio – costo (antes de impuestos)',q.profit]];
container.innerHTML=`<div class="quote-total"><small>Precio ${q.isManual?'manual':'recomendado'} (ARS)</small><strong>${money(q.total)}</strong><p style="font-size:11px;color:#bdd0d1">${esc(markup)} · ${q.quantity} unidad/es · anticipo: ${money(q.deposit)}</p></div><div class="mt">${rows.map(x=>`<div class="stat-line"><span>${x[0]}</span><b>${money(x[1])}</b></div>`).join('')}</div>${q.grams>0&&!n(q.filament_id)?'<div class="notice mt">⚠ Seleccioná el filamento real. No se puede guardar este presupuesto sin su costo.</div>':''}${q.bulkRequested&&!q.isBulk?`<div class="notice mt">El precio por cantidad requiere al menos ${q.bulkMinimum} unidades y trabajo de fabricación. Se aplicó la tarifa normal.</div>`:''}${q.isManual?`<div class="notice mt">Ingresaste un precio manual; la recomendación automática es ${money(q.recommended)}.</div>`:''}${q.profit<0?'<div class="notice mt">ATENCIÓN: el precio final está por debajo del costo estimado.</div>':''}<div class="notice mt">Los factores y descuentos por lote solo se aplican a la fabricación; modelado a tarifa aprobada, sin multiplicador adicional. Cotizá por separado cuando existan varias personalizaciones distintas. No se incluyen impuestos ni comisiones no cargadas en otros costos. Los gramos y horas deben corresponder al pedido completo.</div>`;}
function productionPage(){const a=state.admin,m=a.machines.find(x=>x.id===state.activeMachine)||a.machines[0];if(!m)return titleAdmin('Producción','')+empty('◷','Sin impresoras','Agregá una impresora primero.');const todayValue=today(),weekly=a.weekly.filter(x=>x.machine_id===m.id),jobs=a.requests.filter(x=>x.print_hours>0&&['confirmada','modelando','aprobacion','en_cola','imprimiendo'].includes(x.status));return titleAdmin('Calendario de producción','Franjas variables, turnos nocturnos habilitados y planificación sin interrumpir impresiones.',`<button class="btn" data-action="add-machine">+ Agregar impresora</button>`)+`<div class="toolbar">${selectField('Impresora','machine-select',a.machines.map(x=>[x.id,x.name]),m.id)}<span class="badge ${m.status==='activa'?'green':'amber'}">${esc(m.status)}</span></div><div class="split-equal"><div class="admin-card"><h3>Disponibilidad semanal habitual</h3><p class="muted mb">Cada franja es continua. Podés usar 21:00–07:00 para un turno que termina al día siguiente.</p><form id="weekly-form" data-machine="${m.id}"><div class="grid3">${['Dom','Lun','Mar','Mié','Jue','Vie','Sáb'].map((d,i)=>{const sl=weekly.find(x=>x.weekday===i);return `<label class="switch"><input type="checkbox" name="day_${i}" ${sl?'checked':''}> ${d}</label>`}).join('')}</div><div class="form-grid mt">${field('Inicio','start','time','09:00')}${field('Fin','end','time','17:00')}</div><p class="form-help mt">Esta acción reemplaza el horario semanal por la misma franja para los días seleccionados. Para franjas adicionales o excepciones, usá el calendario por fecha.</p><div class="modal-actions"><button class="btn btn-ghost" type="submit">Guardar semana tipo</button></div></form><hr class="sep"><h3>Excepción para una fecha</h3><p class="muted mb">La fecha elegida reemplaza el horario semanal. Si dejás ambas franjas vacías, ese día queda inhabilitado.</p><form id="shift-form" data-machine="${m.id}"><div class="form-grid">${field('Fecha','date','date',todayValue,'required')}${field('Franja 1 · Inicio','start1','time','09:00')}${field('Franja 1 · Fin','end1','time','17:00')}${field('Franja 2 · Inicio (opcional)','start2','time','')}${field('Franja 2 · Fin (opcional)','end2','time','')}</div><label class="switch mt"><input type="checkbox" name="night_ack"> Confirmo que las franjas nocturnas estarán sujetas a condiciones de seguridad, ventilación y supervisión apropiadas.</label><div class="modal-actions"><button class="btn" type="submit">Guardar disponibilidad</button></div></form></div><div class="admin-card"><h3>Parámetros de la impresora</h3><form id="machine-form" data-id="${m.id}"><div class="form-grid">${field('Nombre','name','text',m.name,'required')}${selectField('Estado','status',['activa','mantenimiento','inactiva'],m.status)}${field('Costo por hora ($)','cost_hour','number',m.cost_hour,'min="0"')}${field('Margen de tiempo (%)','buffer_pct','number',m.buffer_pct,'min="0" max="100"')}${field('Preparación (minutos)','setup_minutes','number',m.setup_minutes,'min="0"')}${field('Notas','notes','text',m.notes||'')}</div><div class="modal-actions"><button class="btn btn-ghost" type="submit">Actualizar máquina</button></div></form><hr class="sep"><h3>Cola y sugerencias</h3>${a.scheduleWarnings.length?`<div class="notice mb">⚠ Hay ${a.scheduleWarnings.length} trabajo(s) fuera de los horarios actualmente disponibles. Revisalos y confirmá los cambios con los clientes.</div>`:''}${jobs.length?jobs.slice(0,15).map(x=>`<div class="stat-line"><div><b>${esc(x.code)}</b><br><span>${n(x.print_hours)} h · ${esc(x.client_name)}</span><br><small>${x.planned_start?datetime(x.planned_start):'Sin turno asignado'}</small></div><button class="btn btn-ghost btn-xs" data-action="schedule-order" data-id="${x.id}">Programar</button></div>`).join(''):empty('◷','Aún no hay trabajos para imprimir','Agregá horas de impresión a un pedido confirmado.')}</div></div>`;}
function isFilamentItem(item){return item.category==='filamento';}
function inventoryQuantity(item,key){return Number(item[key]||0)/(isFilamentItem(item)?1000:1);}
function inventoryQuantityText(item,key){return inventoryQuantity(item,key).toLocaleString('es-AR',{maximumFractionDigits:3})+' '+(isFilamentItem(item)?'kg':item.unit);}
function inventoryUnitPrice(item){return money(n(item.cost_unit)*(isFilamentItem(item)?1000:1))+(isFilamentItem(item)?' / kg':' / '+item.unit);}
function inventoryPage(){const a=state.admin,items=a.inventory,low=items.filter(i=>n(i.available)<=n(i.min_stock));return titleAdmin('Inventario','Filamentos, accesorios, consumibles y movimientos asociados a la producción.',`<button class="btn" data-action="add-inventory">+ Nuevo artículo</button>`)+`<div class="metric-grid">${metric('Artículos registrados',items.length,'▤')}${metric('Filamentos',items.filter(x=>x.category==='filamento').length,'◈')}${metric('Accesorios',items.filter(x=>x.category==='accesorio').length,'✧')}${metric('Alertas de stock',low.length,'⚠')}</div><div class="admin-card"><h3>Existencias actuales</h3>${items.length?`<div class="table-scroll"><table class="data-table"><thead><tr><th>Artículo</th><th>Tipo</th><th>Stock físico</th><th>Reservado</th><th>Disponible</th><th>Mínimo</th><th>Costo unitario</th><th>Situación</th><th></th></tr></thead><tbody>${items.map(x=>`<tr><td><strong>${esc(x.name)}</strong><br><small>${esc([x.material,x.color].filter(Boolean).join(' · '))}</small></td><td>${esc(x.category)}</td><td><strong>${esc(inventoryQuantityText(x,'stock'))}</strong></td><td>${esc(inventoryQuantityText(x,'reserved'))}</td><td><strong>${esc(inventoryQuantityText(x,'available'))}</strong></td><td>${esc(inventoryQuantityText(x,'min_stock'))}</td><td>${esc(inventoryUnitPrice(x))}</td><td><span class="badge ${n(x.available)<=n(x.min_stock)?'amber':'green'}">${n(x.available)<=n(x.min_stock)?'Stock bajo':'Disponible'}</span></td><td><button class="btn btn-ghost btn-xs" data-action="inventory-move" data-id="${x.id}">± Ajustar</button></td></tr>`).join('')}</tbody></table></div>`:empty('▥','Inventario vacío','Registrá tus bobinas de filamento, argollas, cadenas y otros materiales.')}</div><div class="admin-card mt"><div class="flex justify-between" style="align-items:center;gap:12px;flex-wrap:wrap"><div><h3>Precios de mercado (referencias)</h3><p class="muted" style="font-size:12px">Mercado Libre / Proyecto Color. Referencias manuales por 1 kg, no inventario ni stock verificado. Actualizá los valores cuando cambien.</p></div><button class="btn btn-ghost btn-sm" data-action="new-price-ref">+ Nueva referencia</button></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Marca y material</th><th>Color / línea</th><th>Precio 1 kg</th><th>Referencia por gramo</th><th>Fuente y fecha</th><th>Acciones</th></tr></thead><tbody>${(a.filament_prices||[]).map(x=>`<tr><td><b>${esc(x.brand)}</b><br><small>${esc(x.material)}</small></td><td>${esc(x.color||'—')}</td><td>${money(x.kg_price)}</td><td>${money(n(x.kg_price)/1000)}</td><td><small>${esc(x.source)} · ${esc(x.observed_at)}</small>${x.url?`<br><a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">Consultar fuente ↗</a>`:''}</td><td><div class="flex"><button class="btn btn-ghost btn-xs" data-action="new-stock-from-ref" data-id="${x.id}">+ Bobina</button><button class="btn btn-ghost btn-xs" data-action="edit-price-ref" data-id="${x.id}">Editar</button><button class="btn btn-ghost btn-xs" data-action="delete-price-ref" data-id="${x.id}">×</button></div></td></tr>`).join('')}</tbody></table></div><p class="form-help mt">Al cargar una bobina podés cambiar su precio por gramo por el costo real pagado. Las referencias jamás se cuentan como stock.</p></div><div class="admin-card mt"><h3>Últimos movimientos</h3>${a.moves.length?a.moves.slice(0,10).map(x=>`<div class="stat-line"><span>${esc(a.inventory.find(i=>i.id===x.inventory_id)?.name||'Artículo')} · ${esc(x.reason)}</span><b>${n(x.amount)>0?'+':''}${x.amount}</b></div>`).join(''):empty('↗','Sin movimientos','Acá quedarán registrados los consumos y reposiciones.')}</div>`;}
function financesPage(){const a=state.admin,ps=a.payments,ex=a.expenses,inc=ps.reduce((v,x)=>v+n(x.amount),0),spent=ex.reduce((v,x)=>v+n(x.amount),0),sales=a.requests.filter(x=>!['cancelado','rechazado'].includes(x.status)).reduce((v,x)=>v+n(x.quote),0),cost=a.requests.reduce((v,x)=>v+n(x.cost),0);return titleAdmin('Finanzas','Cobros, gastos operativos, anticipos y rentabilidad estimada.',`<button class="btn btn-ghost" data-action="add-expense">+ Registrar gasto</button><button class="btn" data-action="add-payment">+ Registrar cobro</button>`)+`<div class="metric-grid">${metric('Cobros registrados',money(inc),'↗')}${metric('Gastos registrados',money(spent),'↘')}${metric('Caja calculada',money(inc-spent),'◉','Cobrado menos pagado')}${metric('Ventas presupuestadas',money(sales),'▤','Pedidos no cancelados')}</div><div class="notice blue mb">La caja y la rentabilidad no son lo mismo. La caja = cobros menos gastos pagados. La ganancia estimada depende de los costos asignados a cada presupuesto; no incluye impuestos o costos no cargados.</div><div class="split-equal"><div class="admin-card"><h3>Últimos cobros</h3>${ps.length?ps.slice(0,12).map(p=>`<div class="stat-line"><span>${dateES(p.date)} · ${esc(p.method)} ${p.request_id?'· '+esc(a.requests.find(x=>x.id===p.request_id)?.code||'Pedido'):''}</span><b>${money(p.amount)}</b></div>`).join(''):empty('◉','Sin cobros','Cuando confirmes un pago, registralo acá.')}</div><div class="admin-card"><h3>Últimos gastos</h3>${ex.length?ex.slice(0,12).map(e=>`<div class="stat-line"><span>${dateES(e.date)} · ${esc(e.description)}</span><b>${money(e.amount)}</b></div>`).join(''):empty('↘','Sin gastos','Podés registrar insumos, mantenimiento y gastos del emprendimiento.')}</div></div><div class="admin-card mt"><h3>Rentabilidad estimada de presupuestos</h3><div class="stat-line"><span>Total de precios de venta registrados</span><b>${money(sales)}</b></div><div class="stat-line"><span>Costos estimados cargados en pedidos</span><b>${money(cost)}</b></div><div class="stat-line"><span>Diferencia teórica (no es caja ni resultado neto)</span><b>${money(sales-cost)}</b></div></div>`;}
function catalogPage(){const a=state.admin;return titleAdmin('Catálogo web','Los productos activos aparecen automáticamente en la página pública.',`<button class="btn" data-action="add-product">+ Nuevo producto</button>`)+`<div class="product-grid">${a.products.map(p=>`<article class="product-card">${productArt(p)}<div class="product-body"><div class="flex justify-between"><h3>${esc(p.title)}</h3><span class="badge ${p.active?'green':'amber'}">${p.active?'Visible':'Oculto'}</span></div><p>${esc(p.description)}</p><div class="product-foot"><b>${n(p.price)?money(p.price):'A cotizar'}</b><button class="btn btn-ghost btn-sm" data-action="edit-product" data-id="${p.id}">Editar</button><button class="btn btn-ghost btn-sm" data-action="edit-product" data-id="${p.id}">Cambiar foto</button><button class="btn btn-ghost btn-sm" data-action="delete-product" data-id="${p.id}">Eliminar</button></div></div></article>`).join('')}</div>`;}
function reviewsPage(){const a=state.admin,rs=a.reviews,avg=rs.filter(x=>x.status==='publicada').reduce((x,r)=>x+n(r.rating),0)/(rs.filter(x=>x.status==='publicada').length||1);return titleAdmin('Reseñas de clientes','Las opiniones provienen de enlaces únicos de pedidos entregados; podés responderlas y moderar contenido inapropiado.')+`<div class="metric-grid">${metric('Opiniones recibidas',rs.length,'☆')}${metric('Pendientes de revisión',rs.filter(x=>x.status==='pendiente').length,'◷')}${metric('Publicadas',rs.filter(x=>x.status==='publicada').length,'✓')}${metric('Promedio público',rs.some(x=>x.status==='publicada')?avg.toFixed(1).replace('.',',')+'/5':'—','★')}</div><div class="admin-card">${rs.length?rs.map(r=>`<div class="review-moderate"><div class="flex justify-between"><b>${esc(r.name)} · ${'★'.repeat(r.rating)}${'☆'.repeat(5-r.rating)}</b><span class="badge ${r.status==='publicada'?'green':'amber'}">${esc(r.status)}</span></div><p class="mt" style="line-height:1.7">${esc(r.comment)}</p><small>Pedido: ${esc(a.requests.find(x=>x.id===r.request_id)?.code||'?')} · ${dateES(r.created_at)}</small>${r.reply?`<p class="muted mt">Respuesta: ${esc(r.reply)}</p>`:''}<div class="flex mt"><button class="btn btn-ghost btn-sm" data-action="review-status" data-id="${r.id}" data-status="publicada">Publicar</button><button class="btn btn-ghost btn-sm" data-action="review-reply" data-id="${r.id}">Responder</button><button class="btn btn-ghost btn-sm" data-action="review-status" data-id="${r.id}" data-status="oculta">Ocultar spam/datos privados</button></div></div>`).join(''):empty('☆','Sin reseñas todavía','Cuando un pedido se entregue, abrí su ficha para copiar el enlace único y pedir una opinión.')}</div>`;}
function settingsPage(){const s=state.admin.settings;return titleAdmin('Configuración del negocio','Controlá datos de contacto, precios y condiciones sin modificar el código.')+`<div class="split-equal"><div class="admin-card"><h3>Identidad y contacto</h3><form id="settings-contact"><div class="form-grid">${field('Nombre comercial','brand','text',s.brand)}${field('Eslogan','tagline','text',s.tagline)}${field('WhatsApp (código país y área)','whatsapp','tel',s.whatsapp,'placeholder="Ej. 549341..."')}${field('Instagram (URL o @usuario)','instagram','text',s.instagram)}${field('Correo comercial','email','email',s.email)}${field('Zona de atención','city','text',s.city)}${field('Modalidad de retiro','pickup','text',s.pickup)}${field('Condiciones de retiro','delivery_note','text',s.delivery_note)}${field('Horario de atención','business_hours','text',s.business_hours)}</div><div class="modal-actions"><button class="btn" type="submit">Guardar contacto</button></div></form></div><div class="admin-card"><h3>Tarifas y condiciones</h3><form id="settings-pricing"><div class="form-grid">${field('Precio hora modelado ($)','model_rate','number',s.model_rate,'min="0" step="100"')}${field('Mínimo de modelado personalizado ($)','min_model','number',s.min_model,'min="0" step="100"')}${field('Costo interno de hora de diseño ($)','model_cost_rate','number',s.model_cost_rate||5000)}${field('Mano de obra fabricación ($/h)','labor_rate','number',s.labor_rate,'min="0" step="100"')}${field('Mano de obra predeterminada (min/pedido)','labor_default_minutes','number',s.labor_default_minutes,'min="0" step="1"')}${field('Mínimo de impresión ($)','min_print','number',s.min_print)}${field('Impresión por encargo (×)','mult_impresion','number',s.mult_impresion,'min="1" max="10" step="0.1"')}${field('Modelado + impresión, fabricación (×)','mult_modelado_impresion','number',s.mult_modelado_impresion,'min="1" max="10" step="0.1"')}${field('Repuestos y piezas técnicas, fabricación (×)','mult_repuestos','number',s.mult_repuestos,'min="1" max="10" step="0.1"')}${field('Maquetas y proyectos universitarios, fabricación (×)','mult_universitarios','number',s.mult_universitarios,'min="1" max="10" step="0.05"')}${field('Prototipado, fabricación (×)','mult_prototipos','number',s.mult_prototipos,'min="1" max="10" step="0.1"')}${field('Productos de catálogo, fabricación (×)','mult_catalogo','number',s.mult_catalogo,'min="1" max="10" step="0.1"')}${field('Lote chico: desde N unidades','bulk_min_quantity','number',s.bulk_min_quantity,'min="2" step="1"')}${field('Descuento lote chico (%)','bulk_discount_first','number',s.bulk_discount_first,'min="0" max="40" step="1"')}${field('Lote mediano: desde N unidades','bulk_mid_quantity','number',s.bulk_mid_quantity,'min="2" step="1"')}${field('Descuento lote mediano (%)','bulk_discount_mid','number',s.bulk_discount_mid,'min="0" max="40" step="1"')}${field('Lote grande: desde N unidades','bulk_high_quantity','number',s.bulk_high_quantity,'min="2" step="1"')}${field('Descuento lote grande (%)','bulk_discount_high','number',s.bulk_discount_high,'min="0" max="40" step="1"')}${field('Anticipo habitual (%)','deposit_pct','number',s.deposit_pct)}${field('Validez de cotizaciones (días)','quote_validity','number',s.quote_validity)}${field('Desperdicio estimado filamento (%)','material_waste_pct','number',s.material_waste_pct)}${field('Plazo web impresión','public_pla_days','text',s.public_pla_days)}${field('Plazo web trabajos con modelado','public_design_days','text',s.public_design_days)}${field('Plazo web maquetas y proyectos universitarios (con o sin modelado)','public_university_days','text',s.public_university_days)}${field('Plazo web catálogo','public_catalog_days','text',s.public_catalog_days)}</div><div class="modal-actions"><button class="btn" type="submit">Guardar tarifas</button></div></form><div class="notice mt">La web mostrará inmediatamente los datos de contacto y plazos actualizados. Los presupuestos históricos conservan sus precios guardados.</div></div></div><div class="admin-card mt"><h3>Respaldo y seguridad</h3><p class="muted mb" style="line-height:1.8">Descargá un respaldo SQLite completo y consistente, con pedidos, adjuntos, productos, fotos, stock, pagos y reseñas. Conservá el archivo fuera del servidor. El JSON es solo una exportación de consulta.</p><div class="flex"><button class="btn" data-action="backup-db">↓ Respaldo completo SQLite</button><button class="btn btn-ghost" data-action="export-json">↓ Exportar registros JSON</button><button class="btn btn-ghost" data-action="export-csv">↓ Exportar pedidos CSV</button></div></div>`;}

// Interacciones públicas y del panel de administración.
async function reloadAdmin(message){await freshAdmin();await freshPublic();render();if(message)toast(message)}
function selectOrderOptions(){return (state.admin?.requests||[]).map(r=>[r.id,`${r.code} · ${r.client_name}`])}
function waAdminMessage(text){whatsapp(text)}
function reviewLink(r){return `${location.origin}/#opinar/${r.review_token}`}
function openInputModal(title,formId,inputs,description=''){modalOpen(title,`${description?`<p class="muted mb" style="line-height:1.7">${description}</p>`:''}<form id="${formId}">${inputs}<div class="modal-actions"><button type="button" class="btn btn-ghost" data-action="close-modal">Cancelar</button><button type="submit" class="btn">Guardar →</button></div></form>`,true)}
function addInventory(refId=0){
 const ref=(state.admin?.filament_prices||[]).find(x=>x.id===refId);
 openInputModal('Agregar al inventario','inventory-add',`<div class="form-grid">
 ${selectField('Categoría','category',[['filamento','Filamento'],['accesorio','Accesorio'],['consumible','Consumible'],['otro','Otro']],'filamento')}
 ${field('Nombre *','name','text',ref?ref.brand+' '+ref.material:'','required maxlength="100"')}
 ${field('Material *','material','text',ref?.material||'PLA','required maxlength="70"')}
 ${field('Color *','color','text',ref?.color==='Varios'?'':ref?.color||'','required maxlength="70" placeholder="Ej. Negro"')}
 ${selectField('Unidad de carga','unit',[['kg','kg'],['unidad','unidad'],['ml','ml'],['g','g']],'kg')}
 ${field('Stock inicial (kg) *','stock','number','0','required min="0" step="0.001"')}
 ${field('Stock mínimo (kg)','min_stock','number','0.2','min="0" step="0.001"')}
 ${field('Precio por kilogramo ($/kg) *','cost_unit','number',ref?ref.kg_price:'','required min="0.01" step="0.01"')}
 </div>`,'Cargá bobinas en kilogramos: una bobina nueva equivale a 1 kg. El precio debe ser el costo real de compra en $/kg. El sistema convierte todo a gramos para el cotizador y las reservas.');
 syncInventoryCategory();
}
function syncInventoryCategory(){
 const form=$('#inventory-add');if(!form)return;
 const cat=form.querySelector('[name="category"]')?.value||'filamento',isFil=cat==='filamento';
 const unit=form.querySelector('[name="unit"]'),material=form.querySelector('[name="material"]'),color=form.querySelector('[name="color"]');
 if(unit){if(isFil){unit.value='kg';unit.disabled=true;}else{if(unit.disabled)unit.value='unidad';unit.disabled=false;}}
 if(material){material.required=isFil;const label=form.querySelector('label[for="f_material"]');if(label)label.textContent=isFil?'Material *':'Material (opcional)';}
 if(color){color.required=isFil;const label=form.querySelector('label[for="f_color"]');if(label)label.textContent=isFil?'Color *':'Color (opcional)';}
 for(const [name,fil,other] of [['stock','Stock inicial (kg) *','Stock inicial *'],['min_stock','Stock mínimo (kg)','Stock mínimo'],['cost_unit','Precio por kilogramo ($/kg) *','Costo por unidad ($) *']]){
  const label=form.querySelector(`label[for="f_${name}"]`);if(label)label.textContent=isFil?fil:other;
 }
 const cost=form.querySelector('[name="cost_unit"]');if(cost){cost.required=isFil;cost.min=isFil?'0.01':'0';}const minimum=form.querySelector('[name="min_stock"]');if(minimum&&!isFil&&minimum.value==='0.2')minimum.value='0';
}
