async function prepareProductPhoto(file){
 if(!file)return null;
 if(!['image/png','image/jpeg','image/webp','image/avif'].includes(file.type))throw new Error('Usá una imagen JPG, PNG, WebP o AVIF.');
 if(file.size>20_000_000)throw new Error('La imagen original no puede superar los 20 MB.');
 let bitmap;
 try{bitmap=await createImageBitmap(file);}catch{throw new Error('El navegador no pudo abrir la foto. Probá convertirla a JPG o PNG.');}
 try{
  const maxSide=1600;
  const scale=Math.min(1,maxSide/Math.max(bitmap.width,bitmap.height));
  const w=Math.max(1,Math.round(bitmap.width*scale));
  const h=Math.max(1,Math.round(bitmap.height*scale));
  const c=document.createElement('canvas');c.width=w;c.height=h;
  const ctx=c.getContext('2d',{alpha:false});
  ctx.fillStyle='#f4f6f7';ctx.fillRect(0,0,w,h);
  ctx.drawImage(bitmap,0,0,w,h);
  let blob=null;
  for(const quality of [0.9,0.82,0.72,0.62]){
   blob=await new Promise(resolve=>c.toBlob(resolve,'image/webp',quality));
   if(blob && blob.type==='image/webp' && blob.size<=4_800_000)break;
  }
  if(!blob||blob.type!=='image/webp'||blob.size>4_800_000)throw new Error('No se pudo optimizar la foto. Elegí otra imagen.');
  return {mime:'image/webp',data:await readFile(blob)};
 }finally{bitmap.close?.();}
}
let photoObjectURL=null;
function updatePhotoPreview(file){
 const preview=$('#product-photo-preview'),help=$('#product-photo-help'),placeholder=$('#product-photo-placeholder');
 if(!preview)return;
 if(photoObjectURL){URL.revokeObjectURL(photoObjectURL);photoObjectURL=null;}
 if(!file){return;}
 if(!['image/png','image/jpeg','image/webp','image/avif'].includes(file.type)){
  toast('Elegí un archivo JPG, PNG, WebP o AVIF.',true);$('#product-photo-file').value='';return;
 }
 if(file.size>20_000_000){toast('La imagen no puede superar 20 MB.',true);$('#product-photo-file').value='';return;}
 photoObjectURL=URL.createObjectURL(file);preview.src=photoObjectURL;preview.hidden=false;placeholder.hidden=true;
 help.textContent=`Seleccionada: ${file.name} (${(file.size/1024/1024).toFixed(1)} MB). Al guardar se ajustará a 1200 × 1200 sin recortes.`;
}

