// Navegación confiable: los enlaces del panel no dependen de que el navegador
// dispare hashchange. Back/forward se atienden también mediante popstate.
let lastRenderedHash='',routeSeq=0;
async function navigateTo(hash,{historyEntry=true}={}){
  if(historyEntry && location.hash!==hash)history.pushState(null,'',hash);
  const seq=++routeSeq;modalClose();
  // Las solicitudes, cobros y cambios hechos en otra pestaña pueden ser nuevos.
  // Al entrar en cada sección, consultar el servidor sin recargar la página.
  if(String(hash).startsWith('#admin/')&&state.authenticated)await freshAdmin();
  if(seq!==routeSeq)return;
  try{render();lastRenderedHash=location.hash;window.scrollTo(0,0)}
  catch(error){
    console.error('GT-3D: fallo al mostrar sección:',hash,error);
    app.innerHTML=`<main class="admin-login"><section class="login-card"><h1>No pudimos abrir esta sección</h1><p>Los datos no se borraron. Recargá la página o volvé al inicio.</p><p class="muted">${esc(error?.message||'Error desconocido')}</p><a href="#admin/inicio" class="btn">Volver al inicio</a></section></main>`;
    toast('Error al cambiar de sección. Revisá el detalle y volvé a intentar.',true);
  }
}
document.addEventListener('click',event=>{
  const a=event.target.closest?.('a[href^="#"]');if(!a||event.defaultPrevented||event.button!==0||event.metaKey||event.ctrlKey||event.shiftKey||event.altKey)return;
  const hash=a.getAttribute('href');if(!hash||hash==='#')return;
  // Incluye enlaces entre panel y web pública. Las anclas internas públicas
  // conservan el comportamiento nativo de desplazamiento.
  if(hash.startsWith('#admin')||location.hash.startsWith('#admin')){
    event.preventDefault();navigateTo(hash);
  }
});
window.addEventListener('hashchange',()=>{if(location.hash!==lastRenderedHash)navigateTo(location.hash,{historyEntry:false})});
window.addEventListener('popstate',()=>navigateTo(location.hash,{historyEntry:false}));
